/**
 * Kepler integration.
 *
 * GitKraken Kepler organises work as Tasks: a task directory that holds one git
 * worktree per repository plus shared context files (CLAUDE.md / AGENTS.md,
 * generated by Kepler). Agents inside a task reach Kepler through its MCP
 * server (`kepler-workspace`), and Kepler talks to agents over ACP.
 *
 * ORCA fits Kepler in two ways:
 *   1. **Proxy/agent mode** - register `orca acp` as an ACP agent in Kepler; a
 *      Kepler session then drives ORCA, which drives the real agents (see
 *      acp-facade/). This provider makes ORCA runs use the task's worktrees.
 *   2. **Side-car mode** - run `orca` from inside a task folder; the request is
 *      read from the task's AGENTS.md and work happens in the task worktrees.
 */
import { readdir, readFile, stat } from "node:fs/promises";
import { join } from "node:path";
import type { Workspace } from "@orca/core";
import type { ProvisionInput, WorkspaceProvider } from "@orca/engine";

export interface KeplerTaskWorkspaceOptions {
  taskDir: string;
  hostId?: string;
}

export interface KeplerTaskInfo {
  taskDir: string;
  taskId: string | undefined;
  title: string | undefined;
  body: string;
  worktrees: { name: string; path: string }[];
}

export async function inspectKeplerTask(taskDir: string): Promise<KeplerTaskInfo> {
  const worktrees: { name: string; path: string }[] = [];
  for (const entry of await readdir(taskDir, { withFileTypes: true }).catch(() => [])) {
    if (!entry.isDirectory() || entry.name.startsWith(".")) continue;
    const p = join(taskDir, entry.name);
    if (
      await stat(join(p, ".git")).then(
        () => true,
        () => false,
      )
    )
      worktrees.push({ name: entry.name, path: p });
  }
  let title: string | undefined;
  let body = "";
  for (const f of ["AGENTS.md", "CLAUDE.md"]) {
    const text = await readFile(join(taskDir, f), "utf8").catch(() => undefined);
    if (!text) continue;
    const m = /^#\s*Task:\s*(.+)$/m.exec(text);
    title = m?.[1]?.trim();
    body = text
      .split("\n")
      .filter((l) => !l.startsWith("<!--") && !/^#\s*Task:/.test(l))
      .join("\n")
      .trim();
    break;
  }
  const taskId = /tasks[\\/]([0-9a-f-]{36})/i.exec(taskDir)?.[1];
  return { taskDir, taskId, title, body, worktrees };
}

/** Uses the Kepler task's worktrees; picks by work item `repo`, else the only/first worktree, else the task dir. */
export class KeplerTaskWorkspaceProvider implements WorkspaceProvider {
  readonly name = "kepler";
  constructor(private readonly o: KeplerTaskWorkspaceOptions) {}

  async provision(input: ProvisionInput): Promise<Workspace> {
    const info = await inspectKeplerTask(this.o.taskDir);
    const hostId = this.o.hostId ?? "local";
    const wanted = input.workItem?.repo;
    const wt =
      (wanted ? info.worktrees.find((w) => w.name === wanted || w.path === wanted) : undefined) ??
      (input.parent && info.worktrees.find((w) => w.path === input.parent!.cwd)) ??
      info.worktrees[0];
    if (wt) return { hostId, cwd: wt.path, repo: wt.name, provider: this.name };
    return input.parent ?? { hostId, cwd: this.o.taskDir, provider: this.name };
  }
}
